import logging
import os
import shutil

from taf.internal.wireshark.installation import (  # type: ignore[import-untyped]
    install_mcshark,
)

from taf.ul.sbts.pmi_ticket_collector.utils.utils_funcs import (  # type: ignore[import-untyped]
    timer,
)

HOME_DIR: str = os.path.expanduser("~")
PLUGINS_DIR: str = os.path.join(os.path.dirname(__file__), "plugins")
PLUGIN_PROTOBUF_FOLDER: str = os.path.join(HOME_DIR, ".config", "wireshark", "protobuf")
PLUGINS_SOURCE_TARGET_LOCATIONS: dict = {
    os.path.join(PLUGINS_DIR, "to_config_wireshark_plugins", "ccs_decode-0_1_0.lua"): os.path.join(
        HOME_DIR, ".config", "wireshark", "plugins", "ccs_decode-0_1_0.lua"
    ),
    os.path.join(PLUGINS_DIR, "to_config_wireshark_plugins", "sbtsrndcprtpmiticketproto.lua"): os.path.join(
        HOME_DIR, ".config", "wireshark", "plugins", "sbtsrndcprtpmiticketproto.lua"
    ),
    os.path.join(PLUGINS_DIR, "to_config_wireshark_plugins", "gnb_zmtp.lua"): os.path.join(
        HOME_DIR, ".config", "wireshark", "plugins", "gnb_zmtp.lua"
    ),
    os.path.join(PLUGINS_DIR, "to_config_wireshark_protobuf", "cplane"): os.path.join(
        HOME_DIR, ".config", "wireshark", "protobuf", "cplane"
    ),
}


class PluginsInstaller:
    def __init__(self):
        self._logger: logging.Logger = logging.getLogger("pmi_ticket_collector.plugins_installer")

    @timer
    def install_required_wireshark_plugins(self) -> None:
        install_mcshark()
        self._install_other_plugins()

    def _install_other_plugins(self) -> None:
        if not os.path.exists(PLUGIN_PROTOBUF_FOLDER):
            self._logger.debug(f"Created plugin location folder: {PLUGIN_PROTOBUF_FOLDER}")
            os.mkdir(PLUGIN_PROTOBUF_FOLDER)
        for plug_source, plug_target in PLUGINS_SOURCE_TARGET_LOCATIONS.items():
            if not os.path.exists(plug_target):
                self._logger.debug(f"Copying {plug_source} to {plug_target}")
                if os.path.isdir(plug_source):
                    shutil.copytree(plug_source, plug_target)
                else:
                    shutil.copy2(plug_source, plug_target)
            else:
                self._logger.debug(f"Plugin {plug_target} already exists")
